fn solve(m: i8, d: i8) -> i8 {
    // Number of days in each month for a non-leap year
    let days_in_month: i8 = match m {
        1  => 31,
        2  => 28,
        3  => 31,
        4  => 30,
        5  => 31,
        6  => 30,
        7  => 31,
        8  => 31,
        9  => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _  => unreachable!("month must be in 1..=12"),
    };

    // d is the weekday index of the first day (1..=7),
    // so there are (d-1) leading empty slots.
    // Total slots = (d-1) + days_in_month.
    // The number of weeks is ceil(total_slots / 7) = (total_slots + 6) / 7.
    let total_slots = (d - 1) + days_in_month;
    (total_slots + 6) / 7
}